import type { DiscBody } from './DiscBody';
import type { SurfaceMaterial } from './materials';

/** Receives contacts generated by colliders. */
export interface ContactSink {
  add(
    px: number,
    py: number,
    pz: number,
    nx: number,
    ny: number,
    nz: number,
    depth: number,
    mat: SurfaceMaterial,
    tag: string,
  ): void;
}

/** Disc sample points in world space, refreshed every physics step. */
export interface DiscSamples {
  disc: DiscBody;
  /** xyz triples */
  pts: Float64Array;
  count: number;
}

export abstract class Collider {
  minX = 0;
  minY = 0;
  minZ = 0;
  maxX = 0;
  maxY = 0;
  maxZ = 0;
  enabled = true;

  constructor(
    public material: SurfaceMaterial,
    public tag = '',
  ) {}

  overlapsSphere(x: number, y: number, z: number, r: number): boolean {
    return (
      x + r >= this.minX &&
      x - r <= this.maxX &&
      y + r >= this.minY &&
      y - r <= this.maxY &&
      z + r >= this.minZ &&
      z - r <= this.maxZ
    );
  }

  abstract collide(d: DiscSamples, sink: ContactSink): void;
}

/** Oriented box rotated about the vertical axis. */
export class BoxCollider extends Collider {
  private readonly c: number;
  private readonly s: number;

  constructor(
    readonly cx: number,
    readonly cy: number,
    readonly cz: number,
    readonly hx: number,
    readonly hy: number,
    readonly hz: number,
    readonly yaw: number,
    material: SurfaceMaterial,
    tag = 'box',
  ) {
    super(material, tag);
    this.c = Math.cos(yaw);
    this.s = Math.sin(yaw);
    const ex = Math.abs(this.c) * hx + Math.abs(this.s) * hz;
    const ez = Math.abs(this.s) * hx + Math.abs(this.c) * hz;
    this.minX = cx - ex;
    this.maxX = cx + ex;
    this.minY = cy - hy;
    this.maxY = cy + hy;
    this.minZ = cz - ez;
    this.maxZ = cz + ez;
  }

  collide(d: DiscSamples, sink: ContactSink): void {
    const p = d.pts;
    const { c, s, hx, hy, hz } = this;
    for (let i = 0; i < d.count; i++) {
      const dx = p[i * 3] - this.cx;
      const dy = p[i * 3 + 1] - this.cy;
      const dz = p[i * 3 + 2] - this.cz;
      // world -> local (rotation by -yaw about Y)
      const lx = c * dx - s * dz;
      const lz = s * dx + c * dz;
      const ox = hx - Math.abs(lx);
      const oy = hy - Math.abs(dy);
      const oz = hz - Math.abs(lz);
      if (ox <= 0 || oy <= 0 || oz <= 0) continue;
      let nlx = 0;
      let nly = 0;
      let nlz = 0;
      let depth: number;
      if (oy <= ox && oy <= oz) {
        nly = dy >= 0 ? 1 : -1;
        depth = oy;
      } else if (ox <= oz) {
        nlx = lx >= 0 ? 1 : -1;
        depth = ox;
      } else {
        nlz = lz >= 0 ? 1 : -1;
        depth = oz;
      }
      // local -> world (rotation by +yaw)
      const nx = c * nlx + s * nlz;
      const nz = -s * nlx + c * nlz;
      sink.add(p[i * 3], p[i * 3 + 1], p[i * 3 + 2], nx, nly, nz, depth, this.material, this.tag);
    }
  }
}

/** Vertical solid cylinder (tree trunks, poles, pipes, stumps). */
export class CylinderCollider extends Collider {
  constructor(
    readonly cx: number,
    readonly cz: number,
    readonly y0: number,
    readonly y1: number,
    readonly radius: number,
    material: SurfaceMaterial,
    tag = 'cylinder',
  ) {
    super(material, tag);
    this.minX = cx - radius;
    this.maxX = cx + radius;
    this.minY = y0;
    this.maxY = y1;
    this.minZ = cz - radius;
    this.maxZ = cz + radius;
  }

  collide(d: DiscSamples, sink: ContactSink): void {
    const disc = d.disc;
    const R = this.radius;
    // Support test: the rim point that reaches furthest toward the axis. This
    // catches thin poles that pass between sample points.
    {
      const ox = this.cx - disc.x;
      const oz = this.cz - disc.z;
      const dist = Math.hypot(ox, oz);
      if (dist > 1e-6) {
        const ux = ox / dist;
        const uz = oz / dist;
        const n = disc.n;
        const un = ux * n.x + uz * n.z;
        let ex = ux - un * n.x;
        let ey = -un * n.y;
        let ez = uz - un * n.z;
        const el = Math.hypot(ex, ey, ez);
        if (el > 1e-4) {
          ex /= el;
          ey /= el;
          ez /= el;
          const reach = disc.radius * (ex * ux + ez * uz);
          const depth = reach + R - dist;
          if (depth > 0 && depth < disc.radius + R) {
            const px = disc.x + ex * disc.radius;
            const py = disc.y + ey * disc.radius;
            const pz = disc.z + ez * disc.radius;
            if (py >= this.y0 && py <= this.y1) {
              sink.add(px, py, pz, -ux, 0, -uz, depth, this.material, this.tag);
            }
          }
        }
      }
    }
    // Sample points inside the solid (caps and wide cylinders).
    const p = d.pts;
    for (let i = 0; i < d.count; i++) {
      const x = p[i * 3];
      const y = p[i * 3 + 1];
      const z = p[i * 3 + 2];
      if (y <= this.y0 || y >= this.y1) continue;
      const dx = x - this.cx;
      const dz = z - this.cz;
      const r2 = dx * dx + dz * dz;
      if (r2 >= R * R) continue;
      const r = Math.sqrt(r2);
      const side = R - r;
      const top = this.y1 - y;
      const bottom = y - this.y0;
      if (top <= side && top <= bottom) {
        sink.add(x, y, z, 0, 1, 0, top, this.material, this.tag);
      } else if (bottom <= side) {
        sink.add(x, y, z, 0, -1, 0, bottom, this.material, this.tag);
      } else if (r > 1e-6) {
        sink.add(x, y, z, dx / r, 0, dz / r, side, this.material, this.tag);
      }
    }
  }
}

/** Solid sphere, tested exactly against the disc as a thin circular plate. */
export class SphereCollider extends Collider {
  constructor(
    readonly cx: number,
    readonly cy: number,
    readonly cz: number,
    readonly radius: number,
    material: SurfaceMaterial,
    tag = 'sphere',
  ) {
    super(material, tag);
    this.minX = cx - radius;
    this.maxX = cx + radius;
    this.minY = cy - radius;
    this.maxY = cy + radius;
    this.minZ = cz - radius;
    this.maxZ = cz + radius;
  }

  collide(d: DiscSamples, sink: ContactSink): void {
    const disc = d.disc;
    const n = disc.n;
    const dx = this.cx - disc.x;
    const dy = this.cy - disc.y;
    const dz = this.cz - disc.z;
    const dn = dx * n.x + dy * n.y + dz * n.z;
    let px = dx - dn * n.x;
    let py = dy - dn * n.y;
    let pz = dz - dn * n.z;
    const pl = Math.hypot(px, py, pz);
    if (pl > disc.radius) {
      const k = disc.radius / pl;
      px *= k;
      py *= k;
      pz *= k;
    }
    const face = dn >= 0 ? disc.halfThickness : -disc.halfThickness;
    const qx = disc.x + px + n.x * face;
    const qy = disc.y + py + n.y * face;
    const qz = disc.z + pz + n.z * face;
    const ex = qx - this.cx;
    const ey = qy - this.cy;
    const ez = qz - this.cz;
    const dist = Math.hypot(ex, ey, ez);
    if (dist >= this.radius) return;
    if (dist < 1e-6) {
      const s = dn >= 0 ? -1 : 1;
      sink.add(qx, qy, qz, n.x * s, n.y * s, n.z * s, this.radius, this.material, this.tag);
      return;
    }
    sink.add(qx, qy, qz, ex / dist, ey / dist, ez / dist, this.radius - dist, this.material, this.tag);
  }
}

/** Torus (ring frames, basket top band). */
export class TorusCollider extends Collider {
  constructor(
    readonly cx: number,
    readonly cy: number,
    readonly cz: number,
    /** unit axis of the ring */
    readonly ax: number,
    readonly ay: number,
    readonly az: number,
    readonly major: number,
    readonly minor: number,
    material: SurfaceMaterial,
    tag = 'torus',
  ) {
    super(material, tag);
    const e = major + minor;
    this.minX = cx - e;
    this.maxX = cx + e;
    this.minY = cy - e;
    this.maxY = cy + e;
    this.minZ = cz - e;
    this.maxZ = cz + e;
  }

  collide(d: DiscSamples, sink: ContactSink): void {
    const p = d.pts;
    for (let i = 0; i < d.count; i++) {
      const x = p[i * 3];
      const y = p[i * 3 + 1];
      const z = p[i * 3 + 2];
      const dx = x - this.cx;
      const dy = y - this.cy;
      const dz = z - this.cz;
      const along = dx * this.ax + dy * this.ay + dz * this.az;
      let ix = dx - along * this.ax;
      let iy = dy - along * this.ay;
      let iz = dz - along * this.az;
      const il = Math.hypot(ix, iy, iz);
      if (il < 1e-6) continue;
      ix = (ix / il) * this.major;
      iy = (iy / il) * this.major;
      iz = (iz / il) * this.major;
      const vx = dx - ix;
      const vy = dy - iy;
      const vz = dz - iz;
      const dist = Math.hypot(vx, vy, vz);
      if (dist >= this.minor || dist < 1e-6) continue;
      sink.add(x, y, z, vx / dist, vy / dist, vz / dist, this.minor - dist, this.material, this.tag);
    }
  }
}

/** Thin vertical cylindrical wall (basket tray). Pushes points to whichever side they came from. */
export class ShellCollider extends Collider {
  constructor(
    readonly cx: number,
    readonly cz: number,
    readonly y0: number,
    readonly y1: number,
    readonly radius: number,
    readonly thickness: number,
    material: SurfaceMaterial,
    tag = 'shell',
  ) {
    super(material, tag);
    const e = radius + thickness;
    this.minX = cx - e;
    this.maxX = cx + e;
    this.minY = y0;
    this.maxY = y1;
    this.minZ = cz - e;
    this.maxZ = cz + e;
  }

  collide(d: DiscSamples, sink: ContactSink): void {
    const disc = d.disc;
    const centerR = Math.hypot(disc.x - this.cx, disc.z - this.cz);
    const inside = centerR < this.radius;
    const p = d.pts;
    for (let i = 0; i < d.count; i++) {
      const x = p[i * 3];
      const y = p[i * 3 + 1];
      const z = p[i * 3 + 2];
      if (y < this.y0 || y > this.y1) continue;
      const dx = x - this.cx;
      const dz = z - this.cz;
      const r = Math.hypot(dx, dz);
      if (r < 1e-6) continue;
      const ux = dx / r;
      const uz = dz / r;
      if (inside) {
        const depth = r - (this.radius - this.thickness);
        if (depth > 0 && depth < this.thickness * 2 + 0.08) {
          sink.add(x, y, z, -ux, 0, -uz, depth, this.material, this.tag);
        }
      } else {
        const depth = this.radius + this.thickness - r;
        if (depth > 0 && depth < this.thickness * 2 + 0.08) {
          sink.add(x, y, z, ux, 0, uz, depth, this.material, this.tag);
        }
      }
    }
  }
}

/** Axis-aligned ellipsoid (mushroom caps, rounded bumpers). Sample-point based. */
export class EllipsoidCollider extends Collider {
  constructor(
    readonly cx: number,
    readonly cy: number,
    readonly cz: number,
    readonly rx: number,
    readonly ry: number,
    readonly rz: number,
    material: SurfaceMaterial,
    tag = 'ellipsoid',
  ) {
    super(material, tag);
    this.minX = cx - rx;
    this.maxX = cx + rx;
    this.minY = cy - ry;
    this.maxY = cy + ry;
    this.minZ = cz - rz;
    this.maxZ = cz + rz;
  }

  collide(d: DiscSamples, sink: ContactSink): void {
    const p = d.pts;
    const minR = Math.min(this.rx, this.ry, this.rz);
    for (let i = 0; i < d.count; i++) {
      const x = p[i * 3];
      const y = p[i * 3 + 1];
      const z = p[i * 3 + 2];
      const ux = (x - this.cx) / this.rx;
      const uy = (y - this.cy) / this.ry;
      const uz = (z - this.cz) / this.rz;
      const f = ux * ux + uy * uy + uz * uz;
      if (f >= 1) continue;
      let nx = ux / this.rx;
      let ny = uy / this.ry;
      let nz = uz / this.rz;
      const nl = Math.hypot(nx, ny, nz);
      if (nl < 1e-9) {
        nx = 0;
        ny = 1;
        nz = 0;
      } else {
        nx /= nl;
        ny /= nl;
        nz /= nl;
      }
      const depth = (1 - Math.sqrt(f)) * minR;
      sink.add(x, y, z, nx, ny, nz, depth, this.material, this.tag);
    }
  }
}
